contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address caller) public {
        require(caller != address(0), "caller zero");

        address keeperBefore = c.keeper();
        bool pausedBefore = c.paused();

        bool reverted;
        if (caller == keeperBefore) {
            try c.unpauseDeposit() { reverted = false; } catch { reverted = true; }
        } else {
            try c.setKeeper(caller) { reverted = false; } catch { reverted = true; }
            if (!reverted) {
                try c.unpauseDeposit() { reverted = false; } catch { reverted = true; }
            }
        }

        address keeperAfter = c.keeper();
        bool pausedAfter = c.paused();

        if (caller == keeperBefore) {
            assert(!reverted && keeperAfter == keeperBefore && pausedAfter == false);
        } else {
            assert(reverted || (keeperAfter == caller && pausedAfter == false));
        }
    }
}

