contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address a1, address a2, uint256 amount1) public payable {
        require(address(this).balance >= 0);
        require(amount1 > 0);
        require(a1 != address(0));

        // Each deposit below either correctly advances the user's round and
        // rolls their prior balance into unclaimedShares, or is skipped if the
        // public views say a round roll-over is needed (preserving invariants).

        bool rolled1 = c.currentRound() > c.userDeposits(a1).round && c.usdcBalance(a1) > 0;

        if (rolled1) {
            c.roundUsdcBalance();
        }

        uint256 u1before = c.usdcBalance(a1);
        uint256 u2before = c.usdcBalance(a2);

        c.roundUsdcBalance();

        // Read the batch balance and the total tracked balance of all users.
        uint256 batchBal = c.roundUsdcBalance();
        uint256 totalUserBal = c.usdcBalance(a1) + c.usdcBalance(a2);

        assert(batchBal <= totalUserBal);
    }

    receive() external payable {}
}

