contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 depositUsdc, uint256 keeperPayout) public payable {
        require(depositUsdc > 0, "need nonzero usdc deposit");
        require(address(this).balance >= keeperPayout, "not enough ether for keeper payout");

        // Setup: deposit some USDC into the batching manager so it has a USDC balance for the round.
        // We must be the caller and the receiver; if the USDC transfer fails the whole test reverts.
        c.depositUsdc(depositUsdc, address(this));

        // Drive the deciding call: keeper attempts to execute the batch deposit.
        bool reverted;
        try c.executeBatchDeposit() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: if executeBatchDeposit succeeded, any accumulated GLP balance was
        // flushed to zero as part of the batch-deposit completion (or there was none to begin with).
        if (!reverted) {
            assert(c.dnGmxJuniorVaultGlpBalance() == 0);
        } else {
            // If it reverted, the observable rule is vacuously true; we still must reach an assert.
            assert(true);
        }
    }

    receive() external payable {}
}

